#!/usr/bin/env bash
set -euo pipefail
ROOT="/workspaces/advocate-mahbub-website"
cd "$ROOT"

STAMP="$(date +%Y-%m-%d-%H%M%S)"
BACKUP_DIR="backups/hissa-sprint-5-metric-ui-$STAMP"
mkdir -p "$BACKUP_DIR"

cp src/pages/tools/hissa-calculator.astro "$BACKUP_DIR/hissa-calculator.astro"
cp src/styles/hissa-calculator.css "$BACKUP_DIR/hissa-calculator.css"

echo "" | base64 -d > /tmp/hissa-sprint-5-metric-ui.py
python3 /tmp/hissa-sprint-5-metric-ui.py

echo
echo "Running Hissa tests..."
node --test tests/hissa/*.test.js

echo
echo "Running production build..."
npm run build

echo
echo "SUCCESS"
echo "Backup: $BACKUP_DIR"
